set -eu
Q() { runuser -u postgres -- psql -d ameesh -XA -F' | ' -c "$1"; }
echo "== 1. relocatable"; Q "select v.name, v.version, v.installed, v.relocatable, v.schema from pg_available_extension_versions v join pg_extension e on e.extname=v.name and e.extversion=v.version where v.name='pg_stat_statements'"
echo "== 2a. lecteurs (requêtes qui citent pg_stat_statements)"; Q "select r.rolname, count(*) as requetes, sum(calls) as appels, max(left(regexp_replace(query,'\s+',' ','g'),80)) as exemple from pg_stat_statements s left join pg_roles r on r.oid=s.userid where query ilike '%pg_stat_statements%' group by 1 order by 3 desc"
echo "== 2b. pg_stat_activity"; Q "select usename, application_name, client_addr, left(query,60) from pg_stat_activity where query ilike '%pg_stat_statements%' and pid<>pg_backend_pid()"
echo "== 2c. exporteurs/supervision sur l'hôte"; (systemctl list-units --type=service --no-pager --plain 2>/dev/null | grep -iE "export|prometheus|pgwatch|telegraf|datadog|zabbix|netdata|pganalyze" || echo "aucun service de supervision"); (grep -rlis pg_stat_statements /etc --include=*.yml --include=*.yaml --include=*.conf --include=*.toml 2>/dev/null | grep -v postgresql.conf || echo "aucune config hors postgresql.conf")
echo "== 3a. dépendants non-extension des vues"; Q "select classid::regclass, objid, pg_describe_object(classid,objid,objsubid) from pg_depend where refobjid in ('public.pg_stat_statements'::regclass, 'public.pg_stat_statements_info'::regclass) and deptype<>'e' and classid<>'pg_rewrite'::regclass"
echo "== 3a'. vues qui dépendent (via pg_rewrite)"; Q "select distinct v.oid::regclass from pg_depend d join pg_rewrite rw on rw.oid=d.objid join pg_class v on v.oid=rw.ev_class where d.refobjid in ('public.pg_stat_statements'::regclass,'public.pg_stat_statements_info'::regclass) and v.oid not in ('public.pg_stat_statements'::regclass,'public.pg_stat_statements_info'::regclass)"
echo "== 3b. fonctions qui la nomment"; Q "select n.nspname||'.'||p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prosrc ilike '%pg_stat_statements%' and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')"
echo "== autres bases"; for db in $(runuser -u postgres -- psql -XAtc "select datname from pg_database where datallowconn and datname not in ('template1')"); do echo -n "$db: "; runuser -u postgres -- psql -d $db -XAtc "select coalesce((select n.nspname from pg_extension e join pg_namespace n on n.oid=e.extnamespace where extname='pg_stat_statements'),'-')"; done
echo "== shared_preload"; Q "show shared_preload_libraries"
